with v(lesson_id, so, typ, pl) as (values
  ((select l.id from classroom_lessons l join classroom_units u on u.id=l.unit_id join classroom_courses c on c.id=u.course_id
   where c.slug='gg2' and u.title='Unit 4' and l.title='Unit 4 Test'), 0, 'exact_input', $blk${"title": "Посмотри на картинку и напиши слово по-английски", "items": [{"prompt": "", "accept": ["beach", "Beach"], "image": "https://classroom.wowteach.ru/media/gg2/u4/beach.webp"}, {"prompt": "", "accept": ["desert", "Desert"], "image": "https://classroom.wowteach.ru/media/gg2/u4/desert.webp"}, {"prompt": "", "accept": ["island", "Island"], "image": "https://classroom.wowteach.ru/media/gg2/u4/island.webp"}, {"prompt": "", "accept": ["mountain", "Mountain"], "image": "https://classroom.wowteach.ru/media/gg2/u4/mountain.webp"}, {"prompt": "", "accept": ["volcano", "Volcano"], "image": "https://classroom.wowteach.ru/media/gg2/u4/volcano.webp"}, {"prompt": "", "accept": ["waterfall", "Waterfall"], "image": "https://classroom.wowteach.ru/media/gg2/u4/waterfall.webp"}]}$blk$),
  ((select l.id from classroom_lessons l join classroom_units u on u.id=l.unit_id join classroom_courses c on c.id=u.course_id
   where c.slug='gg2' and u.title='Unit 5' and l.title='Unit 5 Test'), 0, 'exact_input', $blk${"title": "Посмотри на картинку и напиши слово по-английски", "items": [{"prompt": "", "accept": ["cinema"], "image": "https://classroom.wowteach.ru/media/gg2/u5/cinema.webp"}, {"prompt": "", "accept": ["library"], "image": "https://classroom.wowteach.ru/media/gg2/u5/library.webp"}, {"prompt": "", "accept": ["museum"], "image": "https://classroom.wowteach.ru/media/gg2/u5/museum.webp"}, {"prompt": "", "accept": ["restaurant"], "image": "https://classroom.wowteach.ru/media/gg2/u5/restaurant.webp"}, {"prompt": "", "accept": ["stadium"], "image": "https://classroom.wowteach.ru/media/gg2/u5/stadium.webp"}, {"prompt": "", "accept": ["theatre", "theater"], "image": "https://classroom.wowteach.ru/media/gg2/u5/theatre.webp"}]}$blk$),
  ((select l.id from classroom_lessons l join classroom_units u on u.id=l.unit_id join classroom_courses c on c.id=u.course_id
   where c.slug='gg2' and u.title='Unit 6' and l.title='Homework 1'), 3, 'exact_input', $blk${"title": "Посмотри на картинку и напиши слово по-английски", "items": [{"prompt": "", "accept": ["doctor", "Doctor"], "image": "https://classroom.wowteach.ru/media/gg2/u6/doctor.webp", "audio_tts": "doctor"}, {"prompt": "", "accept": ["chef", "Chef"], "image": "https://classroom.wowteach.ru/media/gg2/u6/chef.webp", "audio_tts": "chef"}, {"prompt": "", "accept": ["bus driver", "Bus driver"], "image": "https://classroom.wowteach.ru/media/gg2/u6/bus_driver.webp", "audio_tts": "bus driver"}]}$blk$),
  ((select l.id from classroom_lessons l join classroom_units u on u.id=l.unit_id join classroom_courses c on c.id=u.course_id
   where c.slug='gg2' and u.title='Unit 2' and l.title='Unit 2 Test'), 0, 'exact_input', $blk${"title": "Посмотри на картинку и напиши слово по-английски", "items": [{"prompt": "", "accept": ["biscuits", "Biscuits"], "image": "https://classroom.wowteach.ru/media/gg2/u2/biscuits.webp"}, {"prompt": "", "accept": ["cereal", "Cereal"], "image": "https://classroom.wowteach.ru/media/gg2/u2/cereal.webp"}, {"prompt": "", "accept": ["ham", "Ham"], "image": "https://classroom.wowteach.ru/media/gg2/u2/ham.webp"}, {"prompt": "", "accept": ["sausage", "Sausage"], "image": "https://classroom.wowteach.ru/media/gg2/u2/sausage.webp"}, {"prompt": "", "accept": ["water", "Water"], "image": "https://classroom.wowteach.ru/media/gg2/u2/water.webp"}, {"prompt": "", "accept": ["yoghurt", "Yoghurt"], "image": "https://classroom.wowteach.ru/media/gg2/u2/yoghurt.webp"}]}$blk$),
  ((select l.id from classroom_lessons l join classroom_units u on u.id=l.unit_id join classroom_courses c on c.id=u.course_id
   where c.slug='gg2' and u.title='Unit 3' and l.title='Unit 3 Test'), 0, 'exact_input', $blk${"title": "Напиши слово по-английски — по картинке или по русскому слову", "items": [{"prompt": "общаться онлайн", "accept": ["chat online"], "image": "https://classroom.wowteach.ru/media/gg2/u3/chat_online.webp"}, {"prompt": "скачать песню", "accept": ["download a song"], "image": "https://classroom.wowteach.ru/media/gg2/u3/download_song.webp"}, {"prompt": "сидеть в интернете", "accept": ["surf the Internet", "surf the internet"], "image": "https://classroom.wowteach.ru/media/gg2/u3/surf_internet.webp"}, {"prompt": "", "accept": ["tablet", "a tablet"], "image": "https://classroom.wowteach.ru/media/gg2/u3/tablet.webp"}, {"prompt": "", "accept": ["headphones"], "image": "https://classroom.wowteach.ru/media/gg2/u3/headphones.webp"}, {"prompt": "", "accept": ["keyboard", "a keyboard"], "image": "https://classroom.wowteach.ru/media/gg2/u3/keyboard.webp"}]}$blk$),
  ((select l.id from classroom_lessons l join classroom_units u on u.id=l.unit_id join classroom_courses c on c.id=u.course_id
   where c.slug='gg2' and u.title='Unit 6' and l.title='Unit 6 Test'), 0, 'exact_input', $blk${"title": "Посмотри на картинку и напиши слово по-английски", "items": [{"prompt": "", "accept": ["builder", "Builder"], "image": "https://classroom.wowteach.ru/media/gg2/u6/builder.webp"}, {"prompt": "", "accept": ["nurse", "Nurse"], "image": "https://classroom.wowteach.ru/media/gg2/u6/nurse.webp"}, {"prompt": "", "accept": ["pilot", "Pilot"], "image": "https://classroom.wowteach.ru/media/gg2/u6/pilot.webp"}, {"prompt": "", "accept": ["police officer", "Police officer"], "image": "https://classroom.wowteach.ru/media/gg2/u6/police_officer.webp"}, {"prompt": "", "accept": ["shop assistant", "Shop assistant"], "image": "https://classroom.wowteach.ru/media/gg2/u6/shop_assistant.webp"}, {"prompt": "", "accept": ["teacher", "Teacher"], "image": "https://classroom.wowteach.ru/media/gg2/u6/teacher.webp"}]}$blk$),
  ((select l.id from classroom_lessons l join classroom_units u on u.id=l.unit_id join classroom_courses c on c.id=u.course_id
   where c.slug='gg2' and u.title='Unit 7' and l.title='Homework 1'), 3, 'exact_input', $blk${"title": "Посмотри на картинку и напиши слово по-английски", "items": [{"prompt": "", "accept": ["car", "a car"], "image": "https://classroom.wowteach.ru/media/gg2/u7/car.webp", "audio_tts": "car"}, {"prompt": "", "accept": ["boat", "a boat"], "image": "https://classroom.wowteach.ru/media/gg2/u7/boat.webp", "audio_tts": "boat"}, {"prompt": "", "accept": ["bike", "a bike", "bicycle"], "image": "https://classroom.wowteach.ru/media/gg2/u7/bike.webp", "audio_tts": "bike"}, {"prompt": "", "accept": ["bus", "a bus"], "image": "https://classroom.wowteach.ru/media/gg2/u7/bus.webp", "audio_tts": "bus"}, {"prompt": "", "accept": ["motorbike", "a motorbike"], "image": "https://classroom.wowteach.ru/media/gg2/u7/motorbike.webp", "audio_tts": "motorbike"}, {"prompt": "", "accept": ["plane", "a plane"], "image": "https://classroom.wowteach.ru/media/gg2/u7/plane.webp", "audio_tts": "plane"}, {"prompt": "", "accept": ["taxi", "a taxi"], "image": "https://classroom.wowteach.ru/media/gg2/u7/taxi.webp", "audio_tts": "taxi"}, {"prompt": "", "accept": ["train", "a train"], "image": "https://classroom.wowteach.ru/media/gg2/u7/train.webp", "audio_tts": "train"}, {"prompt": "", "accept": ["tram", "a tram"], "image": "https://classroom.wowteach.ru/media/gg2/u7/tram.webp", "audio_tts": "tram"}, {"prompt": "", "accept": ["underground", "the underground"], "image": "https://classroom.wowteach.ru/media/gg2/u7/underground.webp", "audio_tts": "underground"}]}$blk$)),
upd as (update classroom_blocks b set type=v.typ, payload=v.pl::jsonb from v where b.lesson_id=v.lesson_id and b.sort_order=v.so returning b.lesson_id)
select count(*) from upd;